46|export interface Soundtrack {
47|  id: string;
48|  name: string;
49|  style: string;
50|  credit?: string;
51|}
52|
53|export interface MusicManifest {
54|  version: number;
55|  styles: StyleInfo[];
56|  soundtracks: Soundtrack[];
57|  tracks: Track[];
58|  playlists: Playlist[];
59|}
60|
61|// Session selection: style scopes every pick, soundtrackId is the home
62|// in soundtrack mode, mode picks the ranking rule.
63|export interface MusicSelection {
64|  mode: "soundtrack" | "random";
65|  soundtrackId: string | null;
66|  style: string | null;
67|}
68|
69|export type Rng = () => number;
70|
71|export interface SelectEnv {
72|  selection: MusicSelection;
73|  rng: Rng;
74|}
75|
76|export interface PersistedMusicPrefs {
77|  mode: "soundtrack" | "random";
78|  soundtrackId: string | null;
79|  style: string | null;
80|}
81|
82|export interface SceneSignal {
83|  vector: Vector8;
84|  intensity: number;
85|  tempo: number;
86|}
87|
88|export type Similarity = (scene: SceneSignal, track: Track, weights: MusicWeights) => number;
89|
90|export interface MusicWeights {
91|  emotion: number;
92|  intensity: number;
93|  tempo: number;
94|}
95|
96|export interface MusicConfig {
97|  similarity: Similarity;
98|  weights: MusicWeights;
99|  switchMargin: number;
100|  dwellSec: number;
101|  minTrackSec: number;
102|  hardCutMargin: number;
103|  crossfadeSec: number;
104|  hardCutCrossfadeSec: number;
105|  randomTolerance: number;
106|}
107|
108|// Renormalize the 8 entries to sum 1. Extra keys (such as a Jev
109|// "unknown" entry) are ignored. An all-zero vector stays all zero.
110|export function normalize8(vector: Record<string, number>): number[] {
111|  const values = EMOTIONS.map((id: EmotionId) => {
112|    const v = vector[id];
113|    return typeof v === "number" && Number.isFinite(v) ? v : 0;
114|  });
115|  const sum = values.reduce((a, b) => a + b, 0);
116|  if (sum <= 0) return values.map(() => 0);
117|  return values.map((v) => v / sum);
118|}
119|
120|// Bhattacharyya affinity over the renormalized shapes, plus separate
121|// intensity and tempo terms. Fair to blended scenes, unlike cosine.
122|export function bhattacharyyaSimilarity(
123|  scene: SceneSignal,
124|  track: Track,
125|  weights: MusicWeights = MUSIC_CONFIG.weights,
126|): number {
127|  const s = normalize8(scene.vector);
128|  const t = normalize8(track.vector);
129|  let affinity = 0;
130|  for (let i = 0; i < s.length; i++) {
131|    affinity += Math.sqrt((s[i] ?? 0) * (t[i] ?? 0));
132|  }
133|  return (
134|    weights.emotion * affinity +
135|    weights.intensity * (1 - Math.abs(scene.intensity - track.intensity)) +
136|    weights.tempo * (1 - Math.abs(scene.tempo - track.tempo))
137|  );
138|}
139|
140|// Cosine over buildFeatures output (vector plus weighted intensity and
141|// tempo). Kept as an alternative; it favors peaky scenes.
142|export function cosineSimilarity(scene: SceneSignal, track: Track): number {
143|  const a = buildFeatures(scene);
144|  const b = buildFeatures(track);
145|  let dot = 0;
146|  let na = 0;
147|  let nb = 0;
148|  for (let i = 0; i < a.length; i++) {
149|    const x = a[i] ?? 0;
150|    const y = b[i] ?? 0;
151|    dot += x * y;
152|    na += x * x;
153|    nb += y * y;
154|  }
155|  if (na === 0 || nb === 0) return 0;
156|  return dot / (Math.sqrt(na) * Math.sqrt(nb));
157|}
158|
159|export const MUSIC_CONFIG: MusicConfig = {
160|  similarity: bhattacharyyaSimilarity,
161|  weights: { emotion: 0.7, intensity: 0.15, tempo: 0.15 },
162|  switchMargin: 0.07,
163|  dwellSec: 20,
164|  minTrackSec: 45,
165|  hardCutMargin: 0.2,
166|  crossfadeSec: 3,
167|  hardCutCrossfadeSec: 1.5,
168|  // Admits near ties into the random-mode draw without letting clearly
169|  // worse matches in.
170|  randomTolerance: 0.05,
171|};
172|
173|export function resolveConfig(override?: Partial<MusicConfig>): MusicConfig {
174|  if (!override) return MUSIC_CONFIG;
175|  return {
176|    ...MUSIC_CONFIG,
177|    ...override,
178|    weights: override.weights ?? MUSIC_CONFIG.weights,
179|  };
180|}
181|
182|export function scoreTrack(
183|  scene: SceneSignal,
184|  track: Track,
185|  override?: Partial<MusicConfig>,
186|): number {
187|  const config = resolveConfig(override);
188|  return config.similarity(scene, track, config.weights);
189|}
190|
191|// Best score first. Ties go to the lower track id, so ranking is stable.
192|export function rankTracks(
193|  scene: SceneSignal,
194|  manifest: MusicManifest,
195|  override?: Partial<MusicConfig>,
196|): Track[] {
197|  const config = resolveConfig(override);
198|  return [...manifest.tracks].sort((a, b) => {
199|    const diff =
200|      config.similarity(scene, b, config.weights) - config.similarity(scene, a, config.weights);
201|    if (diff !== 0) return diff;
202|    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
203|  });
204|}
205|
206|// Dominant emotion of a scene: argmax of the renormalized vector, with
207|// ties broken by EMOTIONS order.
208|export function dominantEmotion(scene: SceneSignal): EmotionId {
209|  const norm = normalize8(scene.vector);
210|  let best: EmotionId = EMOTIONS[0] as EmotionId;
211|  let bestValue = -Infinity;
212|  EMOTIONS.forEach((id: EmotionId, i: number) => {
213|    const value = norm[i] ?? 0;
214|    if (value > bestValue) {
215|      bestValue = value;
216|      best = id;
217|    }
218|  });
219|  return best;
220|}
221|
222|// Reader skip rule: cycle tracks hand-labeled with the scene's dominant
223|// emotion, in score order, wrapping and skipping the current track. When
224|// the current track has another emotion, start at the top candidate. With
225|// no other same-emotion track, fall back to the best track overall that
226|// Style scope for every pick, minus playlist-only tracks. Playlist tracks
227|// never enter emotion selection, so the filter lives here, not in callers.
228|export function candidatesFor(selection: MusicSelection, manifest: MusicManifest): Track[] {
229|  const audible = manifest.tracks.filter((t) => t.playlistOnly !== true);
230|  if (selection.style === null) return audible;
231|  return audible.filter((t) => t.style === selection.style);
232|}
233|
234|// Home set in soundtrack mode: the session soundtrack, or the whole
235|// style set when none is set yet.
236|export function homeTracks(selection: MusicSelection, styleTracks: Track[]): Track[] {
237|  if (selection.soundtrackId === null) return styleTracks;
238|  const home = styleTracks.filter((t) => t.soundtrack === selection.soundtrackId);
239|  return home.length > 0 ? home : styleTracks;
240|}
241|
242|// "Cambiar track": the next same-emotion track in score order, wrapping
243|// and skipping the current. In soundtrack mode it stays inside the
244|// current track's soundtrack first, then tries the same emotion in other
245|// same-style soundtracks, then the best same-style track overall. In
246|// random mode it ranges over all same-style soundtracks at once. A null
247|// scene cycles the style set in id order. One track or none gives null.
248|export function nextTrack(
249|  scene: SceneSignal | null,
250|  manifest: MusicManifest,
251|  currentTrackId: string | null,
252|  override?: Partial<MusicConfig>,
253|  selection?: MusicSelection | null,
254|): Track | null {
255|  const scope =
256|    selection == null
257|      ? manifest.tracks.filter((t) => t.playlistOnly !== true)
258|      : candidatesFor(selection, manifest);
259|  if (scope.length <= 1) return null;
260|  const config = resolveConfig(override);
261|  const scoped = { ...manifest, tracks: scope };
262|  if (scene === null) {
263|    const ids = [...scope].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
264|    const at = ids.findIndex((t) => t.id === currentTrackId);
265|    return ids[(at + 1) % ids.length] as Track;
266|  }
267|  const ranked = rankTracks(scene, scoped, config);
268|  const same = ranked.filter((t) => t.emotion === dominantEmotion(scene));
269|  const others = same.filter((t) => t.id !== currentTrackId);
270|  if (others.length > 0) {
271|    if (selection?.mode === "random") {
272|      const at = same.findIndex((t) => t.id === currentTrackId);
273|      if (at >= 0) return same[(at + 1) % same.length] as Track;
274|      return same[0] as Track;
275|    }
276|    const current = scope.find((t) => t.id === currentTrackId) ?? null;
277|    const home = current ? same.filter((t) => t.soundtrack === current.soundtrack) : [];
278|    const homeOthers = home.filter((t) => t.id !== currentTrackId);
279|    if (homeOthers.length > 0) {
280|      const at = home.findIndex((t) => t.id === currentTrackId);
281|      if (at >= 0) return home[(at + 1) % home.length] as Track;
282|      return home[0] as Track;
283|    }
284|    const at = same.findIndex((t) => t.id === currentTrackId);
285|    if (at >= 0) return same[(at + 1) % same.length] as Track;
286|    return same[0] as Track;
287|  }
288|  return ranked.find((t) => t.id !== currentTrackId) ?? null;
289|}
290|
291|// Random mode draw: same-style tracks with the scene's dominant emotion
292|// (or the whole style set when none matches), scored, kept within
293|// randomTolerance of the best. The current track stays when eligible;
294|// otherwise the draw skips it when an alternative exists.
295|export function pickRandomTrack(
296|  cands: Track[],
297|  scene: SceneSignal | null,
298|  excludeId: string | null,
299|  rng: Rng,
300|  override?: Partial<MusicConfig>,
301|): Track | null {
302|  if (cands.length === 0) return null;
303|  if (scene === null) {
304|    const ids = [...cands].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
305|    const at = ids.findIndex((t) => t.id === excludeId);
306|    return ids[(at + 1) % ids.length] as Track;
307|  }
308|  const config = resolveConfig(override);
309|  const scoped = { version: 3, styles: [], soundtracks: [], playlists: [], tracks: cands };
310|  const ranked = rankTracks(scene, scoped, config);
311|  const dom = dominantEmotion(scene);
312|  const pool = ranked.filter((t) => t.emotion === dom);
313|  const kept = (pool.length > 0 ? pool : ranked).map((t) => ({
314|    track: t,
315|    score: config.similarity(scene, t, config.weights),
316|  }));
317|  const best = kept[0]?.score ?? 0;
318|  const eligible = kept.filter((e) => e.score >= best - config.randomTolerance);
319|  const current = excludeId !== null ? eligible.find((e) => e.track.id === excludeId) : undefined;
320|  if (current) return current.track;
321|  const rest = eligible.filter((e) => e.track.id !== excludeId);
322|  const drawFrom = rest.length > 0 ? rest : eligible;
323|  if (drawFrom.length === 0) return null;
324|  return (drawFrom[Math.floor(rng() * drawFrom.length)] as { track: Track }).track;
325|}
326|
327|// Distinct hand-labeled emotions on a soundtrack, ignoring playlist-only
328|// tracks. The initial session soundtrack is the one covering most
329|// emotions, ties by lower id.
330|export function soundtrackCoverage(manifest: MusicManifest, soundtrackId: string): number {
331|  return new Set(
332|    manifest.tracks
333|      .filter((t) => t.soundtrack === soundtrackId && t.playlistOnly !== true)
334|      .map((t) => t.emotion),
335|  ).size;
336|}
337|
338|// Best emotion coverage among the given soundtracks, ties by lower id.
339|// Soundtracks with no audible tracks never win.
340|function bestCoverageSoundtrack(manifest: MusicManifest, soundtracks: Soundtrack[]): string | null {
341|  let best: string | null = null;
342|  let bestCover = -1;
343|  for (const s of soundtracks) {
344|    if (!manifest.tracks.some((t) => t.soundtrack === s.id && t.playlistOnly !== true)) continue;
345|    const cover = soundtrackCoverage(manifest, s.id);
346|    if (cover > bestCover || (cover === bestCover && (best === null || s.id < best))) {
347|      best = s.id;
348|      bestCover = cover;
349|    }
350|  }
351|  return best;
352|}
353|
354|export function pickInitialSoundtrack(
355|  manifest: MusicManifest,
356|  persistedId: string | null,
357|): string | null {
358|  if (persistedId !== null && manifest.soundtracks.some((s) => s.id === persistedId)) {
359|    return persistedId;
360|  }
361|  return bestCoverageSoundtrack(manifest, manifest.soundtracks);
362|}
363|
364|// True when the style has at least one emotion-selectable track. The style
365|// selector uses this, so a style with only playlist tracks stays hidden.
366|export function styleHasTracks(manifest: MusicManifest, style: string): boolean {
367|  return manifest.tracks.some((t) => t.style === style && t.playlistOnly !== true);
368|}
369|
370|// Session defaults on load. A stored style with no tracks and a stored
371|// soundtrack outside the stored style both fall back to the defaults.
372|export function resolveInitialSelection(
373|  manifest: MusicManifest,
374|  persisted: PersistedMusicPrefs | null,
375|): MusicSelection {
376|  const fallbackId = pickInitialSoundtrack(manifest, null);
377|  const fallbackStyle =
378|    fallbackId !== null
379|      ? (manifest.soundtracks.find((s) => s.id === fallbackId)?.style ?? null)
380|      : null;
381|  const style =
382|    persisted?.style !== null &&
383|    persisted?.style !== undefined &&
384|    styleHasTracks(manifest, persisted.style)
385|      ? persisted.style
386|      : fallbackStyle;
387|  let soundtrackId: string | null = null;
388|  if (style !== null) {
389|    const inStyle = (id: string) =>
390|      manifest.soundtracks.some((s) => s.id === id && s.style === style);
391|    if (
392|      persisted?.soundtrackId !== null &&
393|      persisted?.soundtrackId !== undefined &&
394|      inStyle(persisted.soundtrackId)
395|    ) {
396|      soundtrackId = persisted.soundtrackId;
397|    } else {
398|      soundtrackId = bestCoverageSoundtrack(
399|        manifest,
400|        manifest.soundtracks.filter((s) => s.style === style),
401|      );
402|    }
403|  }
404|  return {
405|    mode: persisted?.mode === "random" ? "random" : "soundtrack",
406|    soundtrackId,
407|    style,
408|  };
409|}
410|
411|// Style change from user action: the session soundtrack becomes the best
412|// coverage soundtrack in the new style, and the track is the best match
413|// for the scene within the new style. Never crosses styles. Null when
414|// the style has no tracks.
415|export function requestStyleChange(
416|  manifest: MusicManifest,
417|  style: string,
418|  scene: SceneSignal | null,
419|  override?: Partial<MusicConfig>,
420|): { soundtrackId: string; track: Track } | null {
421|  const scoped = manifest.tracks.filter((t) => t.style === style && t.playlistOnly !== true);
422|  if (scoped.length === 0) return null;
423|  const config = resolveConfig(override);
424|  const inStyle = manifest.soundtracks.filter(
425|    (s) => s.style === style && scoped.some((t) => t.soundtrack === s.id),
426|  );
427|  const soundtrackId =
428|    bestCoverageSoundtrack(manifest, inStyle) ?? inStyle[0]?.id ?? scoped[0]?.soundtrack;
429|  if (!soundtrackId) return null;
430|  // Rank inside the picked soundtrack first; the style-wide set is only
431|  // the fallback when the home lacks the scene emotion.
432|  const home = scoped.filter((t) => t.soundtrack === soundtrackId);
433|  if (scene === null) {
434|    const first =
435|      [...home].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))[0] ??
436|      ([...scoped].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))[0] as Track);
437|    return { soundtrackId, track: first };
438|  }
439|  const dom = dominantEmotion(scene);
440|  const emoAcross = scoped.filter((t) => t.emotion === dom);
441|  const scope =
442|    home.some((t) => t.emotion === dom) ? home : emoAcross.length > 0 ? emoAcross : scoped;
443|  const track = rankTracks(scene, { ...manifest, tracks: scope }, config)[0] as Track;
444|  return { soundtrackId, track };
445|}
446|
447|const SUPPORTED_VERSION = 3;
448|const SOURCES = ["generated", "jamendo", "recording"] as const;
449|const SLUG = /^[a-z0-9-]+$/;
450|
451|function isRecord(value: unknown): value is Record<string, unknown> {
452|  return typeof value === "object" && value !== null && !Array.isArray(value);
453|}
454|
455|function isOneOf<T extends string>(value: unknown, allowed: readonly T[]): value is T {
456|  return typeof value === "string" && allowed.some((entry) => entry === value);
457|}
458|
459|function isVector8(value: unknown): value is Vector8 {
460|  if (!isRecord(value)) return false;
461|  return EMOTIONS.every(
462|    (id: EmotionId) =>
463|      typeof value[id] === "number" &&
464|      Number.isFinite(value[id]) &&
465|      (value[id] as number) >= 0 &&
466|      (value[id] as number) <= 1,
467|  );
468|}
469|
470|function isUnit(value: unknown): value is number {
471|  return typeof value === "number" && Number.isFinite(value) && value >= 0 && value <= 1;
472|}
473|
474|function isSrc(value: unknown): value is string {
475|  return (
476|    typeof value === "string" && (value.startsWith("/music/") || value.startsWith("https://"))
477|  );
478|}
479|
480|function isNonEmptyString(value: unknown): value is string {
481|  return typeof value === "string" && value !== "";
482|}
483|
484|// Fail loudly on a bad drop-in manifest so broken files never play quiet.
485|export function parseManifest(json: unknown): MusicManifest {
486|  if (!isRecord(json)) throw new Error("manifest must be an object");
487|  if (json.version !== 3 && json.version !== 2) {
488|    throw new Error(`unsupported manifest version: ${String(json.version)}`);
489|  }
490|  // A v2 manifest becomes one implicit soundtrack holding every track.
491|  if (json.version === 2) {
492|    if (!Array.isArray(json.tracks)) throw new Error("manifest tracks must be an array");
493|    const tracks = json.tracks.map((entry, i) => parseTrack(entry, i, "default", "orchestral"));
494|    return {
495|      version: 3,
496|      styles: [{ id: "orchestral", name: "Orquesta" }],
497|      soundtracks: [{ id: "default", name: "Default", style: "orchestral" }],
498|      tracks,
499|      playlists: [],
