1|// Track selection and manifest parsing. Pure: no env, no fetch, no audio.
2|import { EMOTIONS } from "./types";
3|import type { EmotionId, Vector8 } from "./types";
4|import { buildFeatures } from "./cluster";
5|
6|// Hand label for the track: the single emotion it was made to carry.
7|export type TrackSource = "generated" | "jamendo" | "recording";
8|
9|export interface Playlist {
10|  id: string;
11|  label: string;
12|  trackIds: string[];
13|}
14|
15|// Fixed id for the owner-requested Chopin playlist. The player button
16|// uses the playlist with this id and shows its label verbatim.
17|export const CHOPIN_PLAYLIST_ID = "just-play-chopin";
18|
19|export interface Track {
20|  id: string;
21|  src: string;
22|  title: string;
23|  playlistOnly?: boolean;
24|  emotion: EmotionId;
25|  vector: Vector8;
26|  intensity: number;
27|  tempo: number;
28|  durationSec: number;
29|  startSec: number;
30|  loop: boolean;
31|  soundtrack: string;
32|  style: string;
33|  source?: TrackSource;
34|  artist?: string;
35|  composer?: string;
36|  license?: string;
37|  attribution?: string;
