228|export function candidatesFor(selection: MusicSelection, manifest: MusicManifest): Track[] {
229|  const audible = manifest.tracks.filter((t) => t.playlistOnly !== true);
230|  if (selection.style === null) return audible;
231|  return audible.filter((t) => t.style === selection.style);
232|}
233|
234|// Home set in soundtrack mode: the session soundtrack, or the whole
235|// style set when none is set yet.
236|export function homeTracks(selection: MusicSelection, styleTracks: Track[]): Track[] {
237|  if (selection.soundtrackId === null) return styleTracks;
238|  const home = styleTracks.filter((t) => t.soundtrack === selection.soundtrackId);
239|  return home.length > 0 ? home : styleTracks;
